import json, re
from pathlib import Path
with open('assets/data/53be2d7c_closure_mapping.json','r',encoding='utf-8') as f:
    data=json.load(f)
workspace_files=[]
for p in Path('assets').rglob('*'):
    if p.is_file():
        workspace_files.append(p.as_posix())
# normalize uploaded/ppt filenames by removing leading hash_ if present
norm_map={}
for p in workspace_files:
    name=Path(p).name
    norm=re.sub(r'^[0-9a-f]{8}_','',name)
    norm_map.setdefault(norm,[]).append(p)
matched=[]
unmatched=[]
for group, items in data.items():
    for item in items:
        for sp in item['source_files']:
            base=Path(sp).name
            if base in norm_map:
                matched.append((sp,norm_map[base]))
            else:
                unmatched.append(sp)
print('matched by normalized basename:', len(matched))
for sp, hits in matched[:20]:
    print('SRC:', sp)
    print(' -> ', hits)
print('unmatched count:', len(unmatched))
